import { requestIcon, sanitizeSvg } from '../request';

// setup-tests.js stubs global.DOMParser with a no-op; mock-doc's real parser is still on window.
beforeAll(() => {
  (global as any).DOMParser = (window as any).DOMParser;
});

describe('sanitizeSvg', () => {
  it('keeps a plain svg intact', () => {
    const out = sanitizeSvg('<svg viewBox="0 0 24 24"><path d="M0 0h24v24H0z"></path></svg>');
    expect(out).toContain('<svg');
    expect(out).toContain('viewBox="0 0 24 24"');
    expect(out).toContain('<path d="M0 0h24v24H0z"></path>');
  });

  it('keeps internal use references', () => {
    const out = sanitizeSvg('<svg><defs><path id="a" d="M0"></path></defs><use xlink:href="#a"></use></svg>');
    expect(out).toContain('<use');
    expect(out).toContain('#a');
  });

  it('returns an empty string when the first element is not an svg', () => {
    expect(sanitizeSvg('<div><svg></svg></div>')).toBe('');
    expect(sanitizeSvg('not markup')).toBe('');
  });

  it('strips script and foreignObject elements', () => {
    const out = sanitizeSvg('<svg><script>alert(1)</script><foreignObject><div>x</div></foreignObject><path d="M0"></path></svg>');
    expect(out.toLowerCase()).not.toContain('script');
    expect(out.toLowerCase()).not.toContain('foreignobject');
    expect(out).toContain('<path d="M0"></path>');
  });

  it('strips set, animate, and style elements', () => {
    const out = sanitizeSvg(
      '<svg><a><set attributeName="href" to="javascript:alert(1)"></set><animate attributeName="href" values="javascript:alert(1)"></animate></a><style>.a{fill:red}</style></svg>',
    );
    expect(out).not.toContain('<set');
    expect(out).not.toContain('<animate');
    expect(out).not.toContain('<style');
  });

  it('strips event handler attributes', () => {
    const out = sanitizeSvg('<svg onload="alert(1)"><image href="x" onerror="alert(1)"></image></svg>');
    expect(out.toLowerCase()).not.toContain('onload');
    expect(out.toLowerCase()).not.toContain('onerror');
    expect(out).toContain('href="x"');
  });

  it('strips javascript: urls, including obfuscated ones', () => {
    const out = sanitizeSvg('<svg><a href=" JaVa&#x09;Script:alert(1)"><path></path></a><a xlink:href="javascript:alert(1)"></a></svg>');
    expect(out.toLowerCase()).not.toContain('script:');
  });

  it('removes HTML inside title and desc', () => {
    const out = sanitizeSvg('<svg><title>T<img src="x" onerror="alert(1)"></title><desc><p>hi</p></desc></svg>');
    expect(out).not.toContain('<img');
    expect(out).not.toContain('<p');
    expect(out).not.toContain('onerror');
  });

  it('keeps the svg when preceded by an XML prolog, DOCTYPE, and comment', () => {
    const out = sanitizeSvg(
      '<?xml version="1.0" encoding="UTF-8"?><!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd"><!-- icon --><svg viewBox="0 0 24 24"><path d="M0 0h24v24H0z"></path></svg>',
    );
    expect(out).toContain('<svg');
    expect(out).toContain('<path d="M0 0h24v24H0z"></path>');
  });
});

describe('requestIcon', () => {
  it('sanitizes the fetched svg before returning it', async () => {
    // Verbatim payload from Patchstack #36255.
    const payload = `<svg xmlns="http://www.w3.org/2000/svg"><image href="x-nope"
onerror="var b=document.createElement('div');b.id='scxss';
b.textContent='XSS executed in '+document.domain;
b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:2147483647;background:#8B1A10;color:#fff;padding:16px;font:700 22px system-ui;text-align:center';
document.body.prepend(b)"/></svg>`;

    (global as any).fetch = jest.fn().mockResolvedValue({
      ok: true,
      status: 200,
      text: () => Promise.resolve(payload),
    });

    const file = await requestIcon('https://attacker.example/x.svg');
    expect(file.ok).toBe(true);
    expect(file.svg).toContain('<image');
    expect(file.svg).not.toContain('onerror');
  });
});
